\label{lem:head}
For $0\le t\le1/5$, a zero of $H_t$ with $|\operatorname{Re} z|\le X$ satisfies
$|\operatorname{Im} z|<1/5$.

\label{lem:approx}
If $x\ge6\cdot10^{10}$, $0\le t\le1/5$, and $3\le y\le6$, then
\begin{equation}\label{eq:approx}
 \left|\frac{H_t(z)}{B_t(z)}-
       P_N(s_B,t)-\gamma P_N(s_A,t)\right|<10^{-6}.
\end{equation}
On the subband $4\le y\le6$, one also has
\begin{equation}\label{eq:disk}
 \left|\frac{H_t(z)}{B_t(z)}-1\right|<\frac7{20}.
\end{equation}

\label{prop:triangle-step}
For $x\ge X$ and $0\le t^-\le t\le1/5$, put
$u=\sigma_p+2.78t^-$. Then
\begin{equation}\label{eq:triangle-step}
 S(x,p,t)>\frac{557}{100}-10^{-6}
             -\frac{\nu J(u)+\epsilon_1}{2-Z(u)-\epsilon_0}.
\end{equation}

\label{prop:euler-step}
Let $0\le t^-\le t\le t^+\le1/5$ and $x\ge X$. Define
$u=\sigma_p+5.57t^-$, $m=1/Z(u)$, $K_0=65536$, and
\begin{align}
 \delta_0&=\sum_{n=2}^{K_0}
    (e^{t^+\log^2n/4}-1)n^{-u}+4\cdot10^{-5},\label{eq:delta0}\\
 \delta_1&=\sum_{n=2}^{K_0}
    (e^{t^+\log^2n/4}-1)(\log n)n^{-u}+5\cdot10^{-4}.
       \label{eq:delta1}
\end{align}
If $m>\delta_0+\epsilon_0$, then
\begin{equation}\label{eq:euler-step}
 S(x,p,t)>\frac{557}{100}-10^{-6}
    -\frac{\nu(\psi(u)m+\delta_1)+\epsilon_1}
                 {m-\delta_0-\epsilon_0}.
\end{equation}

\label{lem:kernel-derivative}
Let $p>0$, $B=p^2$, $0<A_2<B$, and $\lambda,\mu\ge0$. For
$D\ge0$ and $0\le r\le A_2$ put
\begin{align}
 w&=D+B-r,\qquad \Delta=w^2+4Dr,\notag\\
 \mathcal N&=2\lambda w\Delta-\mu(2w+4B)\Delta+8\mu Bw^2,\notag\\
 \Phi(D,r)&=2\Delta^2-(D+A_2+3r)\mathcal N.\label{eq:kernel-poly}
\end{align}
If $\Phi(D,r)\ge0$ throughout that domain, then, for
$0<h^2\le A_2$, $0\le v\le h$, and $(d,v)\ne(0,h)$,
\begin{equation}\label{eq:kernel-derivative}
 K_h(d,v)\ge h\left(\frac\lambda p K_p(d,v)
                              -\mu\partial_pK_p(d,v)\right).
\end{equation}

\label{prop:two-density}
If $\varepsilon_0<1/2$, then for $x\ge X$ and $t^-\le t\le t^+$,
\begin{align}
 S(x,p,t)&\ge C^*:=5.5716-10^{-6}-c_1\psi
                         -\frac{\varepsilon_1}{1-\varepsilon_0},
                         \label{eq:new-C}\\
 \partial_pS(x,p,t)&\le G^*:=c_2\psi_2
       +\frac{\varepsilon_2}{1-\varepsilon_0}
       +\left(\frac{\varepsilon_1}{1-\varepsilon_0}\right)^2
       +2\cdot10^{-10}.\label{eq:new-G}
\end{align}
